const body = $input.item.json.body || {};
const id = String(body.auction_id || '').trim();
let maxCents = body.max_cents != null ? parseInt(body.max_cents, 10) : null;
if (!id) return { json: { ok: false, status: 400, error: 'auction_id required' } };
if (maxCents == null || isNaN(maxCents) || maxCents <= 0) return { json: { ok: false, status: 400, error: 'a positive max_cents is required' } };
if (maxCents > 5000000) return { json: { ok: false, status: 422, error: 'max exceeds the $50,000 web limit' } };
const handle = String(body.handle || body.email || body.name || '').trim().slice(0, 120);
return { json: { auction_id: id, max_cents: maxCents, handle: handle } };

let rows = $input.item.json;
if (!Array.isArray(rows)) rows = rows && rows.id ? [rows] : [];
if (rows.length === 0) return { json: { ok: false, status: 404, error: 'Auction not found' } };
const a = rows[0];
const x = $('Extract').item.json;
if (a.status !== 'open' && a.status !== 'extended') return { json: { ok: false, status: 409, error: 'Auction is not accepting bids' } };
const high = a.current_high_bid_cents || 0;
if (x.max_cents <= high) return { json: { ok: false, status: 422, error: 'Your max must be above the current high bid ($' + (high/100).toFixed(2) + ')' } };
return { json: { ok: true, auction_id: x.auction_id, max_cents: x.max_cents, handle: x.handle } };

const s = $input.item.json || {};
const built = $('Build Intent Body').first().json;

if (s.error) {
  // An off-session confirm can be declined for authentication. That is a
  // recoverable step, not a failure: hand back the client_secret so the
  // bidder can complete 3DS. Until they do, the bid is NOT funded and must
  // not count.
  const e = s.error;
  if (e.code === 'authentication_required' && e.payment_intent && e.payment_intent.client_secret) {
    return { json: { ok: true, status: 200,
      payment_intent_id: e.payment_intent.id,
      client_secret: e.payment_intent.client_secret,
      requires_action: true, used_saved_card: true,
      message: 'Your bank needs to verify this. One quick step and your bid is in.' } };
  }
  if (built.saved) {
    // Saved card refused for some other reason (expired, lost, insufficient
    // funds). Do not dead-end the bidder -- let them enter another card.
    return { json: { ok: false, status: 402, retry_with_new_card: true,
      error: 'Your saved card was declined (' + (e.decline_code || e.code || 'declined') +
             '). Please use another card.' } };
  }
  return { json: { ok: false, status: 502, error: 'Stripe: ' + (e.message || e.type || 'create failed') } };
}

if (!s.id) return { json: { ok: false, status: 502,
  error: 'Stripe did not return a PaymentIntent (is STRIPE_SECRET_KEY set?)' } };

// Saved card, already authorised: no card form, nothing more for the bidder.
if (s.status === 'requires_capture') {
  return { json: { ok: true, status: 200, payment_intent_id: s.id,
    authorized: true, used_saved_card: true } };
}
if (s.status === 'requires_action') {
  return { json: { ok: true, status: 200, payment_intent_id: s.id,
    client_secret: s.client_secret, requires_action: true, used_saved_card: true,
    message: 'Your bank needs to verify this. One quick step and your bid is in.' } };
}

// No saved card: unchanged path, the page collects one.
return { json: { ok: true, status: 200, payment_intent_id: s.id,
  client_secret: s.client_secret, used_saved_card: false } };

// One place decides whether this bid needs a card form.
const v = $('Validate').first().json;
let sec = {};
try {
  const b = ($input.item.json || {}).body;
  sec = Array.isArray(b) ? (b[0] || {}) : (b || {});
} catch (e) { sec = {}; }

const usable = sec.ok === true && !sec.banned && sec.customer_id && sec.payment_method_id;

const common = 'amount=' + v.max_cents + '&currency=cad&capture_method=manual'
  + '&payment_method_options[card][request_incremental_authorization]=if_available'
  + '&expand[]=latest_charge'
  + '&metadata[auction_id]=' + v.auction_id
  + '&metadata[kind]=luxi_proxy'
  + '&metadata[max_cents]=' + v.max_cents;

if (!usable) {
  // No saved card: unchanged behaviour, the page collects one.
  return { json: { saved: false, auction_id: v.auction_id, max_cents: v.max_cents,
                   body: common + '&automatic_payment_methods[enabled]=true' } };
}

// Saved card: create AND confirm in one call. off_session tells Stripe the
// bidder is not here to answer a challenge -- it may still demand one, which
// is handled downstream rather than treated as failure.
return { json: { saved: true, auction_id: v.auction_id, max_cents: v.max_cents,
  body: common
    + '&customer=' + encodeURIComponent(sec.customer_id)
    + '&payment_method=' + encodeURIComponent(sec.payment_method_id)
    + '&off_session=true&confirm=true' } };
